{% if product.tags contains 'Limited Stock' %}
  <div class="limited-stock-badge">
    <style>
      .limited-stock-badge {
        margin: 16px 0;
        padding: 16px 20px;
        background: linear-gradient(135deg, #da3f3f 0%, #c41e3a 100%);
        border-radius: 8px;
        border-left: 4px solid #ff6b6b;
        box-shadow: 0 4px 12px rgba(218, 63, 63, 0.2);
        animation: pulse-glow 2s ease-in-out infinite;
      }

      .limited-stock-badge__content {
        display: flex;
        align-items: center;
        gap: 12px;
        color: #ffffff;
      }

      .limited-stock-badge__icon {
        font-size: 24px;
        flex-shrink: 0;
        animation: bounce 1.5s ease-in-out infinite;
      }

      .limited-stock-badge__text {
        flex: 1;
      }

      .limited-stock-badge__title {
        font-size: 16px;
        font-weight: 700;
        margin: 0;
        letter-spacing: 0.5px;
        text-transform: uppercase;
      }

      .limited-stock-badge__subtitle {
        font-size: 13px;
        margin: 4px 0 0 0;
        opacity: 0.95;
        font-weight: 400;
      }

      @keyframes pulse-glow {
        0%, 100% {
          box-shadow: 0 4px 12px rgba(218, 63, 63, 0.2);
        }
        50% {
          box-shadow: 0 4px 20px rgba(218, 63, 63, 0.4);
        }
      }

      @keyframes bounce {
        0%, 100% {
          transform: translateY(0);
        }
        50% {
          transform: translateY(-4px);
        }
      }

      @media (max-width: 768px) {
        .limited-stock-badge {
          padding: 12px 16px;
        }

        .limited-stock-badge__icon {
          font-size: 20px;
        }

        .limited-stock-badge__title {
          font-size: 14px;
        }

        .limited-stock-badge__subtitle {
          font-size: 12px;
        }
      }
    </style>

    <div class="limited-stock-badge__content">
      <div class="limited-stock-badge__icon">⚡</div>
      <div class="limited-stock-badge__text">
        <p class="limited-stock-badge__title">Limited Stock Available</p>
        <p class="limited-stock-badge__subtitle">Renting this book is subject to availability</p>
      </div>
    </div>
  </div>
{% endif %}

