{% assign metafield_namespace = metafield_namespace | default: "custom" %}
{% assign metafield_key = "age_category" | default: "age_category" %}
{% assign chip_bg_color = chip_bg_color | default: "#f7ffaf" %}
{% assign custom_label = custom_label | default: "Age Category" %}

{% assign field_object = product.metafields[metafield_namespace][metafield_key] %}
{% assign field_values = field_object.value %}

{% if custom_label != "" %}
  {% assign field_label = custom_label %}
{% else %}
  {% if field_object.definition and field_object.definition.label != blank %}
    {% assign field_label = field_object.definition.label %}
  {% else %}
    {% assign field_label = metafield_key | capitalize %}
  {% endif %}
{% endif %}

{% if field_values %}
  <div style="display: flex; align-items: center;">
    <!-- Metafield title -->
    <div style="font-size: 16px; font-weight: bold; margin-right: 10px;">
      {{ field_label }}:
    </div>
    <!-- Loop through values to create chips -->
    {% for value in field_values %}
      <span style="
          display: inline-block;
          padding: 0 12px;
          height: 32px;
          line-height: 32px;
          border-radius: 16px;
          background-color: {{ chip_bg_color }};
          color: #333;
          font-size: 14px;
          margin-right: 4px;
        ">
        {{ value }}
      </span>
    {% endfor %}
  </div>
{% else %}
  <p>Unknown {{ field_label | downcase }} </p>
{% endif %}

