settings.liquid:
{% comment %}
  Multiple Metafields Chips Display

  Configuration Format (comma‑separated):
    "namespace:key|chip_bg_color|custom_label"

  Example default:
    "custom:material|#f7ffaf|Material,custom:color|#d5ffd5|Color"

  If you leave custom_label blank, it will try to use the metafield's definition label or fallback to the key.
{% endcomment %}

{% assign metafields_config_str = metafields_config_str | default: "custom:material|#f7ffaf|Material,custom:author|#d5ffd5|,custom:author|#d5ffd5|" %}
{% assign metafields_configurations = metafields_config_str | split: "," %}

{% for config in metafields_configurations %}
  {% assign parts = config | split: "|" %}
  {% assign ns_and_key = parts[0] | strip %}
  {% assign chip_color = parts[1] | default: "#f7ffaf" | strip %}
  {% assign custom_label = parts[2] | strip %}

  {% assign ns_and_key_parts = ns_and_key | split: ":" %}
  {% assign metafield_namespace = ns_and_key_parts[0] | strip %}
  {% assign metafield_key = ns_and_key_parts[1] | strip %}

  {% assign field_object = product.metafields[metafield_namespace][metafield_key] %}
  {% assign field_values = field_object.value %}

  {% if custom_label != "" %}
    {% assign field_label = custom_label %}
  {% else %}
    {% if field_object.definition and field_object.definition.label != blank %}
      {% assign field_label = field_object.definition.label %}
    {% else %}
      {% assign field_label = metafield_key | capitalize %}
    {% endif %}
  {% endif %}

  {% if field_values %}
    <div style="display: flex; align-items: center; margin-bottom: 10px;">
      <!-- Metafield Title -->
      <div style="font-size: 16px; font-weight: bold; margin-right: 10px;">
        {{ field_label }}:
      </div>
      {% if field_values.first %}
        {% for value in field_values %}
          <span style="
              display: inline-block;
              padding: 0 12px;
              height: 32px;
              line-height: 32px;
              border-radius: 16px;
              background-color: {{ chip_color }};
              color: #333;
              font-size: 14px;
              margin-right: 4px;
            ">
            {{ value }}
          </span>
        {% endfor %}
      {% else %}
        <span style="
              display: inline-block;
              padding: 0 12px;
              height: 32px;
              line-height: 32px;
              border-radius: 16px;
              background-color: {{ chip_color }};
              color: #333;
              font-size: 14px;
              margin-right: 4px;
            ">
          {{ field_values }}
        </span>
      {% endif %}
    </div>
  {% else %}
    <p>No {{ field_label | downcase }} available.</p>
  {% endif %}
{% endfor %}
